 if(a==='board-home'){const b=$('.board-viewport');b.scrollTo({left:0,top:0});return;}
 if(a==='import-template'){const book=window.XLSX.utils.book_new(),sheet=window.XLSX.utils.aoa_to_sheet([['手机号','姓名','性别','班级','年龄'],['13800000001','学员甲','男','播音一班',18],['13800000003','学员丙','女','播音二班',18]]);window.XLSX.utils.book_append_sheet(book,sheet,'学生名册');window.XLSX.writeFile(book,'艺风-虚构学生名册模板.xlsx');return;}
 if(a==='export-sample'){assertRole('admin');const rows=[['本场考号','姓名','当前考场','发题时间','原截止','本机状态'],...state.students.filter(x=>!query.get('roomFilter')||x.room===query.get('roomFilter')).map(x=>[x.no,M.person(state,x.id).name,M.room(state,x.room).name,time(x.issue?.issuedAt),time(x.issue?.deadline),queueState(state,x)])],csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='艺风-虚构候选样例.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
