dialog.addEventListener('close',()=>requestAnimationFrame(()=>app.querySelector('[data-action="'+helpReturnAction+'"]')?.focus({preventScroll:true})));
dialog.addEventListener('click',e=>{if(e.target.closest('[data-action=dialog-close]'))dialog.close();});
app.addEventListener('submit',e=>{e.preventDefault();error='';inputs();const form=e.target,fd=new FormData(form);try{switch(form.dataset.form){
 case 'import':assertRole('admin');state.importPreview={signature:String(fd.get('importText')),rows:M.previewImport(String(fd.get('importText')),state)};announce('已生成资料变更预览，尚未写入名册。');break;
 case 'exam':{const n=Number(fd.get('judgeCount'));if(!Number.isInteger(n)||n<1||n>10)throw Error('请选择1–10个评委席位。');M.addToExam(state,ctx,fd.getAll('studentIds').map(String),String(fd.get('examName')).trim(),n);break;}
 case 'paper':assertRole('academic');if(state.exam.status!=='DRAFT')throw Error('本页只在考前维护题卷，已发原卷保持。');{const values=[0,1,2,3].map(i=>String(fd.get('text'+i)||'').trim());if(values.some(x=>!x))throw Error('四段内容均需填写，作品朗读古诗文与现代文不能缺。');const p=structuredClone(paper);p.id='P17-candidate-v'+state.revision;p.parts[0].blocks[0][1]=values[0];p.parts[0].blocks[1][1]=values[1];p.parts[1].blocks[0][1]=values[2];p.parts[2].blocks[0][1]=values[3];state.paperOverride=p;state.exam.paperReady=true;M.event(state,ctx,'保存完整套卷','完整三科已保存为本场候选版本，仍待排场与管理员开放。');}break;
 case 'schedule':assertRole('academic');if(state.exam.status!=='DRAFT')throw Error('已开放场次不在本页直接重排，请管理员使用撤场预览。');{const label=String(fd.get('sessionLabel')||'').trim();if(!label)throw Error('请填写时段名称。');for(const x of state.students){const r=String(fd.get('room-'+x.id));if(!M.room(state,r)?.active)throw Error('所选考场已停用，请重新选择。');x.room=r;}state.exam.session={label};state.exam.arrangementReady=true;M.event(state,ctx,'保存排场','本场时段与逐人考场已保存，交管理员检查开放。');}break;
 case 'quality':Flow.recordQuality(state,ctx,String(fd.get('fileId')),String(fd.get('verdict')),String(fd.get('reason')||''));break;
 case 'checkin':assertRole('student');{const x=M.entry(state,ctx.person),r=M.room(state,x?.room);if(!fd.has('confirm'))throw Error('请先核对本人安排。');if(!x||state.exam.status!=='OPEN'||!r?.active||String(fd.get('code')).trim()!==r.token)throw Error('签到码已过期、原考场已撤回或与本人当前安排不符，请使用当前有效码。');if(!x.signedAt){x.signedAt=M.now(state);x.signRoom=x.room;}M.event(state,ctx,'本人签到','本人签到已登记，等待监考发整套题；重复确认保持原签到时间。');}break;
 case 'review-filter':{const min=String(fd.get('min')),max=String(fd.get('max'));if([min,max].some(v=>v!==''&&(!/^\d+(?:\.\d+)?$/.test(v)||+v<0||+v>100))||min!==''&&max!==''&&+min>+max)throw Error('请填写0–100有效区间，最低分不能高于最高分。');return nav({find:String(fd.get('find')),status:String(fd.get('status')),min,max});}
 case 'business-filter':return nav({roomFilter:String(fd.get('roomFilter')),subjectFilter:String(fd.get('subjectFilter'))});
 default:throw Error('未识别本表单，未记为保存成功。');
 }put();render();}catch(x){error=x.message;render();}});
app.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-zoom]')){sessionStorage.setItem('yf-next-board-zoom',el.value);$('.board-space').style.transform='scale('+el.value+')';return;}if(el.matches('[data-score-key]')){state.drafts[el.dataset.scoreKey]=el.value;put();const hint=$('[data-draft-hint]');if(hint)hint.textContent='当前输入保留在本席位/任务/材料版本，尚未保存评分。';return;}if(el.closest('[data-main-form]'))inputs();});
app.addEventListener('change',async e=>{const el=e.target;error='';try{
 if(el.matches('[data-roster-file]')){const file=el.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('此演示入口只读取10MB以内的样例文件，请使用模板。');const book=window.XLSX.read(await file.arrayBuffer(),{type:'array'});ui.sheets=Object.fromEntries(book.SheetNames.map(name=>[name,window.XLSX.utils.sheet_to_json(book.Sheets[name],{header:1,raw:false,defval:''})]));ui.fileName=file.name;ui.sheet=book.SheetNames[0];selectSheet(ui.sheet);return;}
 if(el.matches('[data-sheet-select]')){selectSheet(el.value);return;}
 if(el.matches('[data-case-sample]')){const sample=M.fresh(page.id,el.value);return nav({scope:sample.scope,case:el.value,run:null,file:null,room:'R1',seat:'reading:1',person:['RE01','RE02','DV01'].includes(page.id)?'B':'A'});}
 if(el.matches('[data-board-extra]')){sessionStorage.setItem('yf-next-board-extra',el.checked?'1':'0');render();return;}
 if(el.matches('[data-role-switch]')){const role=el.value,id=journeys[role]?.[0]||'OP01';return nav({p:id,role,run:null,person:role==='recorder'?'B':'A'});}
 if(el.matches('[data-person-switch]'))return nav({person:el.value,run:null});
 if(el.matches('[data-room-switch]'))return nav({room:el.value,run:null});
 if(el.matches('[data-seat-switch]'))return nav({seat:el.value,run:null});
 if(el.matches('[data-import-exclude]')){const row=state.importPreview?.rows.find(x=>x.row===Number(el.dataset.importExclude));if(row){row.excluded=el.checked;put();render();}return;}
 if(el.matches('[data-device-setting]')){const r=M.room(state,ctx.room);if(M.activeRun(state,ctx.room))throw Error('开始请求后本次方向与镜头已锁定，不能中途变更。');r[el.dataset.deviceSetting]=el.value;announce('考前设备设置样例已保存，开考后锁定。');put();render();}
 }catch(x){error=x.message;render();}});
addEventListener('keydown',e=>{if(e.key==='Escape'&&query.get('display')==='1')nav({display:null});});
addEventListener('popstate',()=>{error='';render();});
addEventListener('storage',e=>{if(page&&e.key==='yf-next-20261109:'+scope)render();});
setInterval(()=>{if(!page||!state)return;if(M.settle(state)){put();render();return;}for(const el of document.querySelectorAll('[data-status-student]')){const p=M.entry(state,el.dataset.statusStudent);if(p){const label=queueState(state,p);if(el.textContent!==label)el.textContent=label;}}let hide=false;for(const el of document.querySelectorAll('[data-clock]')){const [kind,id]=el.dataset.clock.split(':'),p=M.entry(state,id),v=M.run(state,id);const seconds=kind==='prep'?M.remaining(state,p):v?.deadline?Math.max(0,(v.deadline-M.now(state))/1000):0;el.textContent=clock(seconds||0);if(kind==='prep'&&seconds===0&&!$('.student-banner'))hide=true;}if(hide)render();},500);
migrateOldLink();
render();

function selectSheet(name){const rows=ui.sheets[name];if(!rows?.length)throw Error('所选工作表为空，请选择有资料的模板表。');const head=rows[0].map(x=>String(x).trim());if(!['手机号','手机号码'].includes(head[0])||head.slice(1).join(',')!=='姓名,性别,班级,年龄')throw Error('请使用五列模板：手机号、姓名、性别、班级、年龄；列顺序不同请先整理或使用粘贴输入。');if(rows.length>5001)throw Error('此样例入口一次最多预览5000行，请拆分虚构样例。');ui.sheet=name;ui.importText=rows.slice(1).filter(r=>r.some(x=>String(x).trim())).map(r=>r.slice(0,5).join('\t')).join('\n');sessionStorage.setItem(formKey,JSON.stringify(ui));state.importPreview=null;announce('文件已在本机读取，请点击预览核对新增、更新和冲突；不会自动导入。');put();render();}

function migrateOldLink(){
 const alias={teacher:'reviewer',invigilator:'monitor'},initial=new URL(location.href),oldRole=initial.searchParams.get('role');if(alias[oldRole])initial.searchParams.set('role',alias[oldRole]);const oldVersion=initial.searchParams.get('v');if(oldVersion&&parseFloat(oldVersion)<0.20){const f={F02:'F01',F04:'F03',F05:'F04',F06:'F07',F07:'F06',F09:'F05',F10:'F01',F11:'F08',F13:'F07',F14:'F07'}[initial.searchParams.get('feature')];if(f)initial.searchParams.set('feature',f);initial.searchParams.set('v',VERSION);}history.replaceState(null,'',initial);
 const old=location.hash.slice(1),map={A00:'RE01',A01:'DV01',A04:'RE01',A02:'RE01',A07:'DV01',A06:'RE02',A03:'RE03',A05:'RE03',D01:'ST02',S06:'ST02',S03:'ST01',S08:'ST03',M00:'MO01',M01:'MO01',M02:'MO01',M04:'MO01',W06:'RV01',W05:'RV01',W14:'AC02',W04:'AC02',W11:'AD01',W12:'AC01',W03:'AC01',U04:'AD02',U04A:'AD02',W27:'AD05'};
 if(!map[old])return;const id=map[old],u=new URL(location.href);for(const key of ['actor','as','person','q','sample','fixture','walk','step','ref','exam','run','file','case','room','seat'])u.searchParams.delete(key);u.searchParams.set('p',id);u.searchParams.set('scope','legacy-link-v0201-'+id);u.searchParams.set('feature',pages.find(p=>p.id===id).feature);u.searchParams.set('role',pages.find(p=>p.id===id).role);u.searchParams.set('v',VERSION);u.hash='';history.replaceState(null,'',u);
}
